import React, { useState, useEffect } from "react";
import {
  View,
  Text,
  StyleSheet,
  TextInput,
  ScrollView,
  Alert,
  TouchableOpacity,
  Pressable,
} from "react-native";

import { useForm, Controller } from "react-hook-form";

// import { Picker } from "@react-native-picker/picker";

import { Ionicons } from "@expo/vector-icons";
import { postRestaurantDetail } from "../api/Services";
// import { Country, State, City } from "country-state-city";

export default function RegistrationRegistrationScreen() {
  const [showPassword, setShowPassword] = useState(false);
  // const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  // const alertHandler = (msg) => {
  //   Alert.alert("Registration", `${msg}`, [
  //     { text: "OK", onPress: () => null },
  //   ]);
  // };

  const handleRegister = (formValues) => {
    alert(JSON.stringify(formValues));
    postRestaurantDetail(formValues);
  };

  const {
    control,
    handleSubmit,
    reset,
    setValue,
    getValues,
    getFieldState,
    formState: { errors },
  } = useForm({
    defaultValues: {
      owner_name: "",
      email: "",
      mobile_number: "",
      telephone_number: "",
      restaurant_name: "",
      address: "",
      password: "",
      confirmPassword: "",
    },
  });

  return (
    <ScrollView>
      <View style={styles.container}>
        <View style={{ marginTop: 5 }}>
          <Text style={styles.labels}>
            <Text style={{ color: "red", fontWeight: "650" }}>* </Text>
            Name
          </Text>
          <Controller
            control={control}
            name="owner_name"
            rules={{
              required: {
                value: true,
                message: "Owner name is required!",
              },
              pattern: {
                value: /^(?!\s+$).*/,
                message: "Owner name cannot contain only blankspaces!",
              },
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <>
                <View>
                  <TextInput
                    style={styles.input}
                    value={value}
                    onBlur={onBlur}
                    onChangeText={onChange}
                    placeholder="Enter your name"
                    autoCapitalize="none"
                    autoCorrect={false}
                    secureTextEntry={false}
                    placeholderTextColor="#A4A4A4"
                    editable={true}
                    keyboardType="default"
                  />
                </View>

                {errors?.owner_name && (
                  <Text style={styles.textdanger}>{errors?.owner_name?.message}</Text>
                )}
              </>
            )}
          />
        </View>

        <View style={{ marginTop: 5 }}>
          <Text style={styles.labels}>
            <Text style={{ color: "red", fontWeight: "650" }}>* </Text>
            Email
          </Text>
          <Controller
            control={control}
            name="email"
            rules={{
              required: {
                value: true,
                message: "Email is required!",
              },
              pattern: {
                value: /^\w+([\.-]?\w+)*@\w+([\.-]?\w+)*(\.\w{2,3})+$/,
                message: "Email is invalid!",
              },
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <>
                <View>
                  <TextInput
                    style={styles.input}
                    placeholder="Enter your email"
                    autoCapitalize="none"
                    value={value}
                    onBlur={onBlur}
                    onChangeText={onChange}
                    autoCorrect={false}
                    placeholderTextColor="#A4A4A4"
                    keyboardType="email-address"
                  />
                </View>
                {errors?.email && (
                  <Text style={styles.textdanger}>
                    {errors?.email?.message}
                  </Text>
                )}
              </>
            )}
          />
        </View>

        <View style={{ marginTop: 5 }}>
          <Text style={styles.labels}>
            <Text style={{ color: "red", fontWeight: "650" }}>* </Text>
            Mobile Number
          </Text>
          <Controller
            control={control}
            name="mobile_number"
            rules={{
              required: {
                value: true,
                message: "Mobile number is required!",
              },
              pattern: {
                value: /^[6789]\d{9}$/,
                message: "Mobile Number is invalid!",
              },
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <>
                <View>
                  <TextInput
                    style={styles.input}
                    value={value}
                    onBlur={onBlur}
                    onChangeText={onChange}
                    placeholder="Enter your mobile number"
                    autoCapitalize="none"
                    autoCorrect={false}
                    secureTextEntry={false}
                    placeholderTextColor="#A4A4A4"
                    editable={true}
                    keyboardType="number-pad"
                  />
                </View>
                {errors?.mobile_number && (
                  <Text style={styles.textdanger}>
                    {errors?.mobile_number?.message}
                  </Text>
                )}
              </>
            )}
          />
        </View>

        <View style={{ marginTop: 5 }}>
          <Text style={styles.labels}>
            <Text style={{ color: "red", fontWeight: "650" }}>* </Text>
            Telephone Number
          </Text>
          <Controller
            control={control}
            name="telephone_number"
            rules={{
              required: {
                value: true,
                message: "Telephone number is required!",
              },
              pattern: {
                value: /^[6789]\d{9}$/,
                message: "Telephone number is invalid!",
              },
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <>
                <View>
                  <TextInput
                    style={styles.input}
                    value={value}
                    onBlur={onBlur}
                    onChangeText={onChange}
                    placeholder="Enter your Telephone number"
                    autoCapitalize="none"
                    autoCorrect={false}
                    secureTextEntry={false}
                    placeholderTextColor="#A4A4A4"
                    editable={true}
                    keyboardType="number-pad"
                  />
                </View>
                {errors?.telephone_number && (
                  <Text style={styles.textdanger}>
                    {errors?.telephone_number?.message}
                  </Text>
                )}
              </>
            )}
          />
        </View>

        <View style={{ marginTop: 5 }}>
          <Text style={styles.labels}>
            <Text style={{ color: "red", fontWeight: "650" }}>* </Text>
            Password
          </Text>
          <Controller
            control={control}
            name="password"
            rules={{
              required: {
                value: true,
                message: "Password is required!",
              },
              minLength: {
                value: 8,
                message: "Password must be at least 8 characters!",
              },
             
            }}
            render={({
              field: { onChange, onBlur, value },
            
            }) => (
              <>
                <View style={styles.passContainer}>
                  <TextInput
                    style={styles.inputPassword}
                    value={value}
                    onBlur={onBlur}
                    onChangeText={onChange}
                    placeholder="Enter your password"
                    autoCapitalize="none"
                    autoCorrect={false}
                    secureTextEntry={!showPassword}
                    placeholderTextColor="#A4A4A4"
                    editable={true}
                    keyboardType="default"
              
                  />

                  <TouchableOpacity
                    onPress={() => setShowPassword(!showPassword)}
                  >
                    <Ionicons
                      name={showPassword ? "eye" : "eye-off"}
                      size={24}
                      color="black"
                      style={styles.passIcon}
                    />
                  </TouchableOpacity>
                </View>
                {errors?.password && (
                  <Text style={styles.textdanger}>
                    {errors?.password?.message}
                  </Text>
                )}
              </>
            )}
          />
        </View>

        <View style={{ marginTop: 5 }}>
          <Text style={styles.labels}>
            <Text style={{ color: "red", fontWeight: "650" }}>* </Text>
            Confirm Password
          </Text>

          <Controller
            control={control}
            name="confirmPassword"
            rules={{
              required: {
                value: true,
                message: "Confirm password is required!",
              },
              minLength: {
                value: 8,
                message: "Confirm password must be at least 8 characters!",
              },
              validate: (value) =>
                value === getValues("password") ||
                "Password & Confirm Password does not match!",
            }}
            render={({
              field: { onChange, onBlur, value },
              // fieldState: { error },
            }) => (
              <>
                <View style={styles.passContainer}>
                  <TextInput
                    style={styles.inputPassword}
                    value={value}
                    onBlur={onBlur}
                    onChangeText={onChange}
                    placeholder="Enter your password"
                    autoCapitalize="none"
                    autoCorrect={false}
                    secureTextEntry={!showConfirmPassword}
                    placeholderTextColor="#A4A4A4"
                    editable={true}
                    keyboardType="default"
                    // defaultValues={defaultValues}
                  />

                  <TouchableOpacity
                    onPress={() => setShowConfirmPassword(!showConfirmPassword)}
                  >
                    <Ionicons
                      name={showConfirmPassword ? "eye" : "eye-off"}
                      size={24}
                      color="black"
                      style={styles.passIcon}
                    />
                  </TouchableOpacity>
                </View>
                {/* {errors?.confirmPassword && (
                  <Text style={styles.textdanger}>
                    {errors?.confirmPassword?.message}
                  </Text>
                )} */}
              </>
            )}
          />
        </View>

        <View style={{ marginTop: 5 }}>
          <Text style={styles.labels}>
            <Text style={{ color: "red", fontWeight: "650" }}>* </Text>
            Restaurant name
          </Text>
          <Controller
            control={control}
            name="restaurant_name"
            rules={{
              required: {
                value: true,
                message: "Restaurant name is required!",
              },
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <>
                <View>
                  <TextInput
                    style={styles.input}
                    value={value}
                    onBlur={onBlur}
                    onChangeText={onChange}
                    placeholder="Enter Restaurant name"
                    autoCapitalize="none"
                    autoCorrect={false}
                    secureTextEntry={false}
                    placeholderTextColor="#A4A4A4"
                    editable={true}
                    keyboardType="default"
                    // defaultValues={defaultValues}
                  />
                </View>

                {errors?.restaurant_name && (
                  <Text style={styles.textdanger}>
                    {errors?.restaurant_name?.message}
                  </Text>
                )}
              </>
            )}
          />
        </View>

        <View style={{ marginTop: 5 }}>
          <Text style={styles.labels}>
            <Text style={{ color: "red", fontWeight: "650" }}>* </Text>
            Address
          </Text>
          <Controller
            control={control}
            name="address"
            rules={{
              required: {
                value: true,
                message: "Address is required!",
              },
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <>
                <View>
                  <TextInput
                    style={styles.input}
                    value={value}
                    onBlur={onBlur}
                    onChangeText={onChange}
                    placeholder="Enter address"
                    autoCapitalize="none"
                    autoCorrect={false}
                    secureTextEntry={false}
                    placeholderTextColor="#A4A4A4"
                    editable={true}
                    keyboardType="default"
                    // defaultValues={defaultValues}
                  />
                </View>

                {errors?.address && (
                  <Text style={styles.textdanger}>
                    {errors?.address?.message}
                  </Text>
                )}
              </>
            )}
          />
        </View>

        <View style={{ marginBottom: 30, marginHorizontal: 10, marginTop: 10 }}>
          <Pressable
            onPress={handleSubmit(handleRegister)}
            // disabled={!isValid}
            style={{
              backgroundColor: "#841584",
              height: 40,
              alignItems: "center",
              justifyContent: "center",
              borderRadius: 3,
            }}
          >
            <Text
              style={{
                color: "white",
                fontSize: 16,
                fontWeight: "bold",
              }}
            >
              Register
            </Text>
          </Pressable>
        </View>
      </View>
    </ScrollView>
  );
}

